window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5f0f4e562cf97b30"]={"versions": [{"id": "FIG-5f0f4e562cf97b30", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses des Teilschritts „Write Counter“ innerhalb der Funktion <code>E2E_P07mForward()</code> des AUTOSAR E2E-Profils 7m (PRS_E2E_00813). Das Diagramm modelliert die bedingte Anpassung und anschließende Serialisierung des Übertragungszählers (<code>Counter</code>) in die Nutzdaten eines weiterzuleitenden E2E-Datenstroms.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionskontext</strong>: <code>E2E_P07mForward()</code>\n</li><li><strong>Zustands- und Konfigurationsstrukturen</strong>:\n<ul class=\"fig-list\"><li><code>State-&gt;Counter</code>: Zählervariable (laut Notiz vom Typ <code>uint16</code>, Wertebereich <code>0x0000</code> bis <code>0xFFFF</code> mit Überlauf zu <code>0</code>).\n</li><li><code>Config-&gt;MaxDeltaCounter</code>: Konfigurierte maximale Zählerdifferenz für Folgebilderkennung.\n</li><li><code>ForwardStatus</code>: Statusindikator des Weiterleitungsschritts mit den Enumerationswerten <code>E2E_P_REPEATED</code> und <code>E2E_P_WRONGSEQUENCE</code>.\n</li></ul>\n</li><li><strong>Datenpuffer</strong>: Byte-Array <code>Data[]</code> mit Adressierungsbereich <code>Data[Offset+12...Offset+15]</code> (4 Bytes Nutzdatenfeld).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialer Eintritt</strong>: Start am Initialknoten nach Aufruf von <code>E2E_P07mForward()</code>.\n</li><li><strong>Erste Verzweigung (<code>if ForwardStatus == E2E_P_REPEATED</code>)</strong>:\n<ul class=\"fig-list\"><li><code>[TRUE]</code>: Dekrementierung des Zählers (<code>State-&gt;Counter--</code>).\n</li><li><code>[FALSE]</code>: Weiterleitung zur nächsten Verzweigungsbedingung.\n</li></ul>\n</li><li><strong>Zweite Verzweigung (<code>if ForwardStatus == E2E_P_WRONGSEQUENCE</code>)</strong>:\n<ul class=\"fig-list\"><li><code>[TRUE]</code>: Erhöhung des Zählers um den Maximalabstand (<code>State-&gt;Counter = State-&gt;Counter + Config-&gt;MaxDeltaCounter</code>).\n</li><li><code>else</code>: Keine Zähleranpassung.\n</li></ul>\n</li><li><strong>Zusammenführung (Merge)</strong>: Alle drei Pfade vereinigen sich in einem gemeinsamen Verbindungsknoten.\n</li><li><strong>Aktion „Write Counter“</strong>: Kopieren des 4-Byte-Wertes von <code>State-&gt;Counter</code> in Big-Endian-Byte-Reihenfolge auf <code>Data[Offset+12...Offset+15]</code>.\n</li><li><strong>Ablauftermination</strong>: Erreichen des Aktivitätsendknotens.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Anforderung</strong>: Realisiert Anforderung <code>[PRS_E2E_00813]</code> zur konsistenten Zählerfortführung bei wiederholten oder fehlerhaft sequenzierten Nachrichten im Weiterleitungspfad.\n</li><li><strong>Widerspruch / Implementierungshinweis</strong>: Die angehängte Notiz spezifiziert den Zähler explizit als <code>uint16</code> mit Überlaufverhalten nach <code>0xFFFF</code> auf <code>0</code>. Die Schreiboperation serialisiert den Wert jedoch als 4-Byte-Feld (<code>Copy 4-byte State-&gt;Counter on bytes Data[Offset+12...Offset+15] in Big Endian order</code>). Implementierungen müssen sicherstellen, dass die 16-Bit-Zählervariable typgerecht im 32-Bit-Pufferbereich (Offset+12 bis Offset+15) formatiert bzw. zero-extended wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6b526ceac2b3d417", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses des Teilschritts „Write Counter“ innerhalb der Funktion <code>E2E_P07mForward()</code> des AUTOSAR E2E-Profils 7m (PRS_E2E_00813). Das Diagramm modelliert die bedingte Anpassung und anschließende Serialisierung des Übertragungszählers (<code>Counter</code>) in die Nutzdaten eines weiterzuleitenden E2E-Datenstroms.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionskontext</strong>: <code>E2E_P07mForward()</code>\n</li><li><strong>Zustands- und Konfigurationsstrukturen</strong>:\n<ul class=\"fig-list\"><li><code>State-&gt;Counter</code>: Zählervariable (laut Notiz vom Typ <code>uint16</code>, Wertebereich <code>0x0000</code> bis <code>0xFFFF</code> mit Überlauf zu <code>0</code>).\n</li><li><code>Config-&gt;MaxDeltaCounter</code>: Konfigurierte maximale Zählerdifferenz für Folgebilderkennung.\n</li><li><code>ForwardStatus</code>: Statusindikator des Weiterleitungsschritts mit den Enumerationswerten <code>E2E_P_REPEATED</code> und <code>E2E_P_WRONGSEQUENCE</code>.\n</li></ul>\n</li><li><strong>Datenpuffer</strong>: Byte-Array <code>Data[]</code> mit Adressierungsbereich <code>Data[Offset+12...Offset+15]</code> (4 Bytes Nutzdatenfeld).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialer Eintritt</strong>: Start am Initialknoten nach Aufruf von <code>E2E_P07mForward()</code>.\n</li><li><strong>Erste Verzweigung (<code>if ForwardStatus == E2E_P_REPEATED</code>)</strong>:\n<ul class=\"fig-list\"><li><code>[TRUE]</code>: Dekrementierung des Zählers (<code>State-&gt;Counter--</code>).\n</li><li><code>[FALSE]</code>: Weiterleitung zur nächsten Verzweigungsbedingung.\n</li></ul>\n</li><li><strong>Zweite Verzweigung (<code>if ForwardStatus == E2E_P_WRONGSEQUENCE</code>)</strong>:\n<ul class=\"fig-list\"><li><code>[TRUE]</code>: Erhöhung des Zählers um den Maximalabstand (<code>State-&gt;Counter = State-&gt;Counter + Config-&gt;MaxDeltaCounter</code>).\n</li><li><code>else</code>: Keine Zähleranpassung.\n</li></ul>\n</li><li><strong>Zusammenführung (Merge)</strong>: Alle drei Pfade vereinigen sich in einem gemeinsamen Verbindungsknoten.\n</li><li><strong>Aktion „Write Counter“</strong>: Kopieren des 4-Byte-Wertes von <code>State-&gt;Counter</code> in Big-Endian-Byte-Reihenfolge auf <code>Data[Offset+12...Offset+15]</code>.\n</li><li><strong>Ablauftermination</strong>: Erreichen des Aktivitätsendknotens.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Anforderung</strong>: Realisiert Anforderung <code>[PRS_E2E_00813]</code> zur konsistenten Zählerfortführung bei wiederholten oder fehlerhaft sequenzierten Nachrichten im Weiterleitungspfad.\n</li><li><strong>Widerspruch / Implementierungshinweis</strong>: Die angehängte Notiz spezifiziert den Zähler explizit als <code>uint16</code> mit Überlaufverhalten nach <code>0xFFFF</code> auf <code>0</code>. Die Schreiboperation serialisiert den Wert jedoch als 4-Byte-Feld (<code>Copy 4-byte State-&gt;Counter on bytes Data[Offset+12...Offset+15] in Big Endian order</code>). Implementierungen müssen sicherstellen, dass die 16-Bit-Zählervariable typgerecht im 32-Bit-Pufferbereich (Offset+12 bis Offset+15) formatiert bzw. zero-extended wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-5f0f4e562cf97b30", "to": "FIG-6b526ceac2b3d417", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
